    void picture(String url,ImageView view,int token){view.setTag(url);pictureViews.put(view,new ImageTask(url,view,token));Bitmap cached=pictures.get(url);if(cached!=null){view.setImageBitmap(cached);return;}pendingPictures.put(view,new ImageTask(url,view,token));view.post(()->{ui.removeCallbacks(visiblePictures);ui.postDelayed(visiblePictures,40);});}
    void fetchPicture(String url,ImageView view,int token){Bitmap cached=pictures.get(url);if(cached!=null){view.setImageBitmap(cached);return;}if(!imageRequests.add(view))return;imageIo.execute(()->{try{if(token!=renderVersion)return;Bitmap prior=pictures.get(url);if(prior!=null){ui.post(()->{if(!isDestroyed()&&token==renderVersion&&url.equals(view.getTag()))view.setImageBitmap(prior);});return;}HttpURLConnection c=null;try{URL address=new URL(url);if(!address.getProtocol().equals("https"))return;c=(HttpURLConnection)address.openConnection();c.setConnectTimeout(7000);c.setReadTimeout(8000);c.setInstanceFollowRedirects(false);if(c.getResponseCode()!=200)return;byte[] bytes;try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>5_000_000)return;out.write(b,0,n);}bytes=out.toByteArray();}BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);int sample=1;int maxWidth=url.contains("/w1280/")?1600:400,maxHeight=url.contains("/w1280/")?1000:600;while(o.outWidth/sample>maxWidth||o.outHeight/sample>maxHeight)sample*=2;o.inSampleSize=sample;o.inJustDecodeBounds=false;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(bitmap!=null)pictures.put(url,bitmap);ui.post(()->{if(!isDestroyed()&&token==renderVersion&&bitmap!=null&&url.equals(view.getTag()))view.setImageBitmap(bitmap);});}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}}finally{imageRequests.remove(view);}});}
