    void loadPlaylist(boolean force){
        if(!playlistTab())return;String section=category;boolean live=section.equals("LiveTV");
        PlaylistStore.Snapshot existing=playlists.get(section);
        if(!force&&existing!=null&&(!live||System.currentTimeMillis()-existing.updated<M3uPlaylist.LIVE_TTL)){scheduleLiveRefresh();return;}
        if(!playlistLoading.add(section))return;playlistErrors.remove(section);render();
        io.execute(()->{
            PlaylistStore.Snapshot cached=existing;
            if(cached==null)try{cached=PlaylistStore.cached(getApplicationContext(),live);}catch(IOException ignored){}
            final PlaylistStore.Snapshot fallback=cached;
            if(cached!=null)ui.post(()->{if(isDestroyed())return;playlists.put(section,fallback);if(category.equals(section))render();});
            try{
                PlaylistStore.Snapshot result=!force&&cached!=null&&(!live||System.currentTimeMillis()-cached.updated<M3uPlaylist.LIVE_TTL)?cached:PlaylistStore.fetch(getApplicationContext(),live);
                ui.post(()->{if(isDestroyed())return;playlistLoading.remove(section);playlists.put(section,result);playlistErrors.remove(section);if(category.equals(section)){renderPlaylistPreservingPosition();scheduleLiveRefresh();}});
            }catch(Exception error){ui.post(()->{if(isDestroyed())return;playlistLoading.remove(section);playlistErrors.put(section,"Refresh unavailable. "+(fallback==null?"Check your connection and try again.":"Showing the last saved channels."));if(category.equals(section)){renderPlaylistPreservingPosition();scheduleLiveRefresh();}});}
        });
    }
    void scheduleLiveRefresh(){
        ui.removeCallbacks(liveRefresh);if(!foreground||!category.equals("LiveTV"))return;
        PlaylistStore.Snapshot list=playlists.get("LiveTV");long delay=list==null?60_000:Math.max(60_000,M3uPlaylist.LIVE_TTL-(System.currentTimeMillis()-list.updated));ui.postDelayed(liveRefresh,delay);
    }
