    static final class GenreImageTask {final String type;final int id,token;final ImageView image;GenreImageTask(String type,int id,ImageView image,int token){this.type=type;this.id=id;this.image=image;this.token=token;}}
    void genrePicture(String type,int id,ImageView image,int token){
        String key=type+id,url=genreArtwork.get(key);
        if(url==null)for(Catalog.Item item:browse){if(!ContentApi.media(item).equals(type))continue;JSONArray genres=item.raw.optJSONArray("genreIds");if(genres==null)continue;for(int i=0;i<genres.length();i++)if(genres.optInt(i)==id){url=item.raw.optString("backdrop");if(url.isEmpty())url=item.poster;if(!url.isEmpty())break;}if(url!=null&&!url.isEmpty())break;}
        if(url!=null&&!url.isEmpty()){genreArtwork.put(key,url);picture(url,image,token);return;}
        pendingGenreArtwork.put(image,new GenreImageTask(type,id,image,token));image.post(()->ui.post(visiblePictures));
    }
    void loadVisibleGenreArtwork(){
        Rect visible=new Rect();Iterator<Map.Entry<ImageView,GenreImageTask>> iterator=pendingGenreArtwork.entrySet().iterator();List<GenreImageTask> tasks=new ArrayList<>();while(iterator.hasNext()){Map.Entry<ImageView,GenreImageTask> entry=iterator.next();GenreImageTask task=entry.getValue();if(task.token!=renderVersion){iterator.remove();continue;}if(entry.getKey().isShown()&&entry.getKey().getGlobalVisibleRect(visible)){tasks.add(task);iterator.remove();}}
        for(GenreImageTask task:tasks){String key=task.type+task.id;String cached=genreArtwork.get(key);if(cached!=null){picture(cached,task.image,task.token);continue;}if(!genreArtworkLoading.add(key)){pendingGenreArtwork.put(task.image,task);continue;}String apiKey=tmdbKey();io.execute(()->{String url="";try{List<Catalog.Item> examples=ContentApi.tmdbRows((task.id==-16?ContentApi.animeData(apiKey,task.type,1):ContentApi.categoryData(apiKey,task.type,task.id,1)).getJSONArray("results"),task.type,false);for(Catalog.Item item:examples){url=item.raw.optString("backdrop");if(url.isEmpty())url=item.poster;if(!url.isEmpty())break;}}catch(Exception ignored){}final String art=url;ui.post(()->{genreArtworkLoading.remove(key);if(isDestroyed())return;if(!art.isEmpty()){genreArtwork.put(key,art);if(task.token==renderVersion&&category.equals("Categories"))picture(art,task.image,task.token);ui.post(visiblePictures);}});});}
    }

    @Override protected void onDestroy(){stopPreview();if(eggAnimation!=null)eggAnimation.cancel();DirectDownloads.get(this).listener=null;++searchVersion;++loadVersion;++renderVersion;ui.removeCallbacksAndMessages(null);io.shutdownNow();imageIo.shutdownNow();pendingPictures.clear();pictureViews.clear();pictures.evictAll();super.onDestroy();}    void addToggle(LinearLayout panel,String label,String key){Switch toggle=new Switch(this);toggle.setText(label+(prefs.getBoolean(key,true)?" · ON":" · OFF"));toggle.setTextColor(prefs.getBoolean(key,true)?ACCENT:MUTED);toggle.setChecked(prefs.getBoolean(key,true));toggle.setFocusable(true);toggle.setPadding(0,dp(10),0,dp(10));toggle.setOnCheckedChangeListener((b,on)->{prefs.edit().putBoolean(key,on).apply();toggle.setText(label+(on?" · ON":" · OFF"));toggle.setTextColor(on?ACCENT:MUTED);stopPreview();});panel.addView(toggle);}
    void applyPalette(String name){String[] colors=name.equals("light")?new String[]{"#f3f5f9","#ffffff","#182130","#536174","#0a715e"}:name.equals("ocean")?new String[]{"#081b29","#102c3d","#effbff","#afcad7","#79e2bd"}:name.equals("orchid")?new String[]{"#18132b","#29203d","#fff5fd","#cbbbda","#efb3dc"}:name.equals("sunset")?new String[]{"#101b2d","#1b2d45","#fff8eb","#bac9da","#ffc478"}:new String[]{"#090a10","#161c29","#f4f6fc","#b0bbcc","#65e6cc"};BG=Color.parseColor(colors[0]);SURFACE=Color.parseColor(colors[1]);INK=Color.parseColor(colors[2]);MUTED=Color.parseColor(colors[3]);ACCENT=Color.parseColor(colors[4]);lightTheme=name.equals("light");}
