    void recolor(View view,int[] before){int[] after={BG,SURFACE,INK,MUTED,ACCENT};if(view instanceof TextView){TextView text=(TextView)view;int current=text.getCurrentTextColor();boolean matched=false;for(int i=0;i<before.length;i++)if(current==before[i]){text.setTextColor(after[i]);matched=true;break;}if(!matched){if(current==0xFFF4F5FA||current==0xFFF4F6FC||current==0xFF182130)text.setTextColor(INK);else if(current==0xFF9DA2B5||current==0xFFB0BBCC||current==0xFF536174)text.setTextColor(MUTED);else if(current==0xFF65E6CC||current==0xFF54E5C1||current==0xFF0A715E)text.setTextColor(ACCENT);}}if(view instanceof Switch){Switch toggle=(Switch)view;toggle.setThumbTintList(android.content.res.ColorStateList.valueOf(toggle.isChecked()?ACCENT:MUTED));toggle.setTrackTintList(android.content.res.ColorStateList.valueOf((ACCENT&0xFFFFFF)|0x55000000));}android.graphics.drawable.Drawable background=view.getBackground();if(background instanceof android.graphics.drawable.ColorDrawable){int color=((android.graphics.drawable.ColorDrawable)background).getColor();for(int i=0;i<before.length;i++)if(color==before[i])view.setBackgroundColor(after[i]);}else if(background instanceof GradientDrawable&&Build.VERSION.SDK_INT>=24){android.content.res.ColorStateList color=((GradientDrawable)background).getColor();if(color!=null)for(int i=0;i<before.length;i++)if(color.getDefaultColor()==before[i])((GradientDrawable)background).setColor(after[i]);}if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)recolor(((ViewGroup)view).getChildAt(i),before);}
