    String downloadStateKey(JSONArray jobs){StringBuilder value=new StringBuilder();for(int i=0;i<jobs.length();i++){JSONObject j=jobs.optJSONObject(i);value.append(j.optString("id")).append(j.optString("state"));}return value.toString();}
    int downloadPercent(JSONObject j){return j.optLong("total")>0?(int)Math.min(100,100d*j.optLong("bytes")/j.optLong("total")):0;}
    String downloadStats(JSONObject j){long speed=j.optLong("speed"),total=j.optLong("total"),bytes=j.optLong("bytes");return j.optString("state")+" · "+(total>0?downloadPercent(j)+"% · ":"")+downloadSize(bytes)+" / "+downloadSize(total)+" · "+downloadSize(speed)+"/s"+(speed>0&&total>bytes?" · "+((total-bytes)/speed/60+1)+" min remaining":"");}
    AlertDialog confirmDeleteDownload(JSONObject j){AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Delete Video?").setMessage(j.optString("title")+"\n"+downloadSize(j.optLong("bytes"))+"\nThe actual local video file will be permanently deleted.").setNegativeButton("Cancel",null).setPositiveButton("Delete Video",(d,n)->downloadAction(j.optString("id"),"delete")).create();dialog.setOnShowListener(d->{dialog.getButton(AlertDialog.BUTTON_NEGATIVE).setFocusableInTouchMode(true);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setFocusableInTouchMode(true);dialog.getButton(AlertDialog.BUTTON_NEGATIVE).requestFocus();});dialog.show();return dialog;}
    void downloadAction(String id,String action){try{DirectDownloads.get(this).action(id,action);render();}catch(Exception e){message(e.getMessage());}}
    void openDownloaded(JSONObject j){File file=new File(j.optString("file"));if(!file.isFile()){render();message("Video file is missing.");return;}try{JSONObject source=new JSONObject().put("url",android.net.Uri.fromFile(file).toString()).put("mimeType",j.optString("mime","video/mp4"));startActivity(new Intent(this,PlayerActivity.class).putExtra("stream",source.toString()).putExtra("title",j.optString("title")).putExtra("key","download:"+j.optString("id")).putExtra("parent","download:"+j.optString("id")));}catch(Exception e){message("Could not open downloaded video.");}}
