    void easterEgg(){if(eggMode){exitEgg();return;}if(++logoPresses!=10)return;eggMode=true;switchPalette("orchid");eggExit=button("Exit Easter Egg",this::exitEgg);FrameLayout root=(FrameLayout)getWindow().getDecorView().findViewById(android.R.id.content);FrameLayout.LayoutParams layout=new FrameLayout.LayoutParams(-2,dp(44),Gravity.BOTTOM|Gravity.LEFT);layout.setMargins(dp(12),0,0,dp(BuildConfig.TV?12:64));root.addView(eggExit,layout);eggAnimation=android.animation.ValueAnimator.ofFloat(.85f,1f);eggAnimation.setDuration(2600);eggAnimation.setRepeatCount(android.animation.ValueAnimator.INFINITE);eggAnimation.setRepeatMode(android.animation.ValueAnimator.REVERSE);eggAnimation.addUpdateListener(a->{if(SystemClock.elapsedRealtime()-eggPaint<500)return;eggPaint=SystemClock.elapsedRealtime();float f=(float)a.getAnimatedValue();if(eggExit!=null)eggExit.setAlpha(f);ACCENT=(int)new android.animation.ArgbEvaluator().evaluate((f-.85f)/.15f,0xFF9FECFF,0xFFEFB3DC);if(eggLogo!=null)eggLogo.setTextColor(ACCENT);if(sidebar!=null){if(eggSidebar==null){eggSidebar=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0xFF242150,0xFF351B3E,0xFF102D3F});sidebar.setBackground(eggSidebar);}eggSidebar.setStroke(dp(2),ACCENT);}View focus=getCurrentFocus();if(focus instanceof Button)focus.setBackground(shape(SURFACE,ACCENT));});if(prefs.getBoolean("uiAnimations",true))eggAnimation.start();message("Color mode activated");}
